/* СВЕДЕНИЯ О ТЕКСТЕ. Считает то, что в строке состояния не поместится:
   предложения и их среднюю длину, самые длинные абзацы, частые слова, доли
   заголовков и таблиц. Всё — по снимку документа, в своём потоке; ни сети, ни
   доступа к странице у плагина нет.

   «Следить» — считать заново при каждой правке и при каждом переходе курсора:
   события приходят не чаще раза в 150 мс, и счёт идёт по снимку, который у
   потока уже есть. */

const ПУСТЫЕ = ('и,в,во,не,что,он,на,я,с,со,как,а,то,все,она,так,его,но,да,ты,к,у,же,вы,за,бы,по,только,'
  + 'ее,мне,было,вот,от,меня,еще,нет,о,из,ему,теперь,когда,даже,ну,вдруг,ли,если,уже,или,ни,быть,был,'
  + 'него,до,вас,нибудь,опять,уж,вам,ведь,там,потом,себя,ничего,ей,может,они,тут,где,есть,надо,ней,для,'
  + 'мы,тебя,их,чем,была,сам,чтоб,без,будто,чего,раз,тоже,себе,под,будет,ж,тогда,кто,этот,того,потому,'
  + 'этого,какой,совсем,ним,здесь,этом,один,почти,мой,тем,чтобы,нее,сейчас,были,куда,зачем,всех,никогда,'
  + 'можно,при,наконец,два,об,другой,хоть,после,над,больше,тот,через,эти,нас,про,всего,них,какая,много,'
  + 'разве,три,эту,моя,впрочем,хорошо,свою,этой,перед,иногда,лучше,чуть,том,нельзя,такой,им,более,всегда,'
  + 'конечно,всю,между,это,не,также,том,этих,своих,данный,который,которые,которых').split(',');
const СОР = new Set(ПУСТЫЕ);

const ЗАГОЛОВОК = /^H[1-6]$/;
const слова = т => String(т).toLowerCase().match(/[a-zа-яё][a-zа-яё-]*/g) || [];
/* Предложение кончается точкой, «?», «!» или «…», за которыми пробел или конец.
   Сокращения вроде «т. д.» дают ложный конец — их считаем за одно, отбрасывая
   куски короче трёх слов при подсчёте средней длины. */
const предложения = т => String(т).split(/(?<=[.!?…])[\s ]+/).map(s => s.trim()).filter(Boolean);

function посчитать(){
  const блоки = документ.блоки;
  const из = {абзацев: 0, заголовков: 0, таблиц: 0, списков: 0, слов: 0, знаков: 0, безПробелов: 0,
              предложений: 0, вПредложении: 0, длинных: [], частые: [], пустых: 0};
  const счёт = new Map();
  let длинныеПредложения = 0, словВПредложениях = 0, предложенийДлинных = 0;
  блоки.forEach((б, и) => {
    const тег = String(б.тег || '').toUpperCase();
    if(тег === 'TABLE'){ из.таблиц++; }
    else if(тег === 'UL' || тег === 'OL'){ из.списков++; }
    else if(ЗАГОЛОВОК.test(тег)) из.заголовков++;
    else из.абзацев++;
    const т = String(б.текст || '');
    if(!т.trim()){ из.пустых++; return; }
    из.знаков += т.length;
    из.безПробелов += т.replace(/[\s ]/g, '').length;
    const сл = слова(т);
    из.слов += сл.length;
    for(const с of сл){ if(с.length < 4 || СОР.has(с)) continue; счёт.set(с, (счёт.get(с) || 0) + 1); }
    for(const п of предложения(т)){
      const n = слова(п).length;
      if(!n) continue;
      из.предложений++;
      if(n >= 3){ словВПредложениях += n; предложенийДлинных++; }
      if(n > 30) длинныеПредложения++;
    }
    if(!ЗАГОЛОВОК.test(тег) && сл.length) из.длинных.push({и: и, слов: сл.length, начало: т.slice(0, 40)});
  });
  из.вПредложении = предложенийДлинных ? Math.round(словВПредложениях / предложенийДлинных * 10) / 10 : 0;
  из.длинныеПредложения = длинныеПредложения;
  из.длинных.sort((a, b) => b.слов - a.слов);
  из.длинных = из.длинных.slice(0, 5);
  из.частые = [...счёт.entries()].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0], 'ru')).slice(0, 8);
  return из;
}

const число = n => Number(n).toLocaleString('ru-RU');

function показать(){
  const п = параметры({}), с = посчитать();
  const ряды = [
    ['Слов', число(с.слов)],
    ['Знаков', число(с.знаков)],
    ['Знаков без пробелов', число(с.безПробелов)],
    ['Абзацев', число(с.абзацев) + (с.пустых ? ' (пустых ' + с.пустых + ')' : '')],
    ['Заголовков', число(с.заголовков)],
    ['Таблиц и списков', число(с.таблиц) + ' и ' + число(с.списков)],
    ['Предложений', число(с.предложений)],
    ['Слов в предложении', с.вПредложении ? String(с.вПредложении) : '—'],
    ['Длинных (больше 30 слов)', число(с.длинныеПредложения)],
    ['Страниц по 1800 знаков', с.знаков ? String(Math.max(1, Math.round(с.знаков / 1800 * 10) / 10)) : '0'],
  ];
  панель.список('итоги', ряды);
  панель.список('длинные', с.длинных.map(д => ['абзац ' + (д.и + 1), д.слов + ' сл. · ' + д.начало]));
  панель.список('частые', с.частые.map(([с2, n]) => [с2, число(n)]));
  хранилище.положить('последние', {слов: с.слов, знаков: с.знаков});
  панель.сообщение(с.знаков ? '' : 'Документ пуст — считать нечего');
  return с;
}

function Обновить(){ return показать(); }
function Старт(){ показать(); }

/* Следить: считать заново по правке и по переходу курсора. Флажок выключен —
   события приходят, но ничего не делаем: так плагин не мешает набирать. */
function приИзменении(){ if(параметры({}).следить !== false) показать(); }
function приВыделении(){ if(параметры({}).следить !== false) показать(); }

/* Перейти к самому длинному абзацу: плагин просит, курсор ставит приложение. */
function КСамому(){
  const с = посчитать();
  if(!с.длинных.length){ панель.сообщение('Длинных абзацев нет'); return; }
  документ.перейти(с.длинных[0].и);
  панель.сообщение('Абзац ' + (с.длинных[0].и + 1) + ': слов ' + с.длинных[0].слов);
}
